//! Gold: `dw-model` is 1:1 with the live `local_model.py` reference.
//!
//! `tests/fixtures/gold/model_v1.json` was generated by
//! `scripts/gold_model.py` — every case computed by the reference itself.
//! The cases pin the deterministic core: byte-identical `local_prompt`
//! strings (both JSON encodings), `focused_page_context` region filtering
//! and digital-text truncation, `validate_response` error messages, and
//! `parse_json_response` fence-stripping / raw-decode edge cases.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_model::{focused_page_context, local_prompt, parse_json_response, validate_response};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/model_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let expected = &case["expected"];
        match case["kind"].as_str().unwrap() {
            "local_prompt" => {
                let cap = input["capability"].as_str().unwrap();
                let pe = &input["page_evidence"];
                let include = input["include_page_evidence"].as_bool().unwrap();
                let got = local_prompt(cap, pe, include);
                match &got {
                    Ok(s) => {
                        assert_eq!(
                            serde_json::Value::String(s.clone()),
                            *expected,
                            "case {name}"
                        );
                    }
                    Err(e) => {
                        panic!("case {name}: unexpected error {e}");
                    }
                }
            }
            "focused_page_context" => {
                let cap = input["capability"].as_str().unwrap();
                let pe = &input["page_evidence"];
                let got = focused_page_context(cap, pe).unwrap();
                assert_eq!(got, *expected, "case {name}");
            }
            "validate_response" => {
                let value = &input["value"];
                let schema = &input["schema"];
                let result = validate_response(value, schema, "$");
                match expected {
                    Value::Null => {
                        assert!(result.is_ok(), "case {name}: expected ok, got {result:?}");
                    }
                    Value::String(msg) => {
                        assert!(result.is_err(), "case {name}: expected error");
                        let err = result.unwrap_err();
                        assert_eq!(err.message(), msg, "case {name}");
                    }
                    other => panic!("case {name}: unexpected expected type {other}"),
                }
            }
            "parse_json_response" => {
                let text = input["text"].as_str().unwrap();
                let result = parse_json_response(text);
                match expected {
                    Value::Object(_) | Value::Array(_) => {
                        assert_eq!(result.unwrap(), *expected, "case {name}");
                    }
                    Value::String(msg) => {
                        assert!(result.is_err(), "case {name}: expected error");
                        let err = result.unwrap_err();
                        assert_eq!(err.message(), msg, "case {name}");
                    }
                    other => panic!("case {name}: unexpected expected type {other}"),
                }
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}

/// Negative control: the two JSON encodings in `local_prompt` must differ.
/// Evidence uses compact separators; the schema uses default separators.
/// If both collapse to the same encoding the prompt bytes change.
#[test]
fn prompt_uses_two_json_encodings() {
    let pe = serde_json::json!({
        "document_sha256": "abc",
        "page_1based": 1,
        "blocks": [{"bbox": [0, 0, 1, 1], "text": "x"}],
        "tables": [],
        "digital_text": null,
        "structural_evidence": null
    });
    let prompt = local_prompt("parametrics", &pe, true).unwrap();
    // Evidence encoding (compact): `"text":"x"` — no space after colon.
    assert!(
        prompt.contains("\"text\":\"x\""),
        "evidence should use compact separators (no space after colon)"
    );
    // Schema encoding (default): `"type": "object"` — space after colon.
    assert!(
        prompt.contains("\"type\": \"object\""),
        "schema should use default separators (space after colon)"
    );
}
